{
  "name": "remote-agent-browser",
  "version": "1.3.0",
  "description": "Run agent-browser in a Vercel Sandbox created from a browser-ready container image",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vercel-labs/remote-agent-browser.git"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "packageManager": "pnpm@11.18.0",
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bunchee --runtime node",
    "benchmark": "node --run build && node benchmarks/chromium.mjs",
    "prepublishOnly": "node --run build",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "node --run build && node --test tests/*.test.mjs",
    "test:integration": "node --run build && node --test --test-concurrency=1 tests/*.integration.ts",
    "test:unit": "node --run build && node --test tests/unit.test.mjs"
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@vercel/sandbox": "^2.9.0"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "bunchee": "^7.0.0",
    "typescript": "^5.9.0"
  }
}

import { randomUUID } from 'node:crypto'
import type {
  BrowserCommandResult,
  BrowserRunResult,
  BrowserShellResult,
  BrowserClientOptions,
  CommandRunner,
  ExecOptions,
  JsonExecOptions,
  KeepaliveOptions,
  ProxyOptions,
  AgentBrowser,
  RunOptions,
  ShellOptions,
} from './types.js'

type FileSpec = { ext: string; contentType: string }

const FLAGS_WITH_VALUE = new Set([
  '--screenshot-dir',
  '--screenshot-quality',
  '--screenshot-format',
  '--format',
  '--width',
  '--height',
  '--margin',
  '--scale',
])

const SESSION_NAME = /^[\w.-]{1,64}$/
const DEFAULT_COMMAND_TIMEOUT_MS = 60_000
const PROXY_FLAGS = ['--proxy', '--proxy-bypass']

function proxyEnvironment(
  proxy: ProxyOptions | undefined,
): Record<string, string> | undefined {
  if (proxy === undefined) return undefined
  const url = typeof proxy === 'string' ? proxy : proxy.url
  const bypass = typeof proxy === 'string' ? undefined : proxy.bypass
  if (url.length === 0) {
    throw new RangeError('proxy url must not be empty')
  }
  const env: Record<string, string> = {
    AGENT_BROWSER_PROXY: url,
  }
  if (bypass !== undefined) {
    const serialized =
      typeof bypass === 'string' ? bypass : bypass.join(',')
    if (serialized.length === 0) {
      throw new RangeError('proxy bypass must not be empty')
    }
    env.AGENT_BROWSER_PROXY_BYPASS = serialized
  }
  return env
}

function hasProxyFlag(args: string[]): boolean {
  return args.some((arg) =>
    PROXY_FLAGS.some((flag) => arg === flag || arg.startsWith(`${flag}=`)),
  )
}

function proxyOutputRedactor(proxy: ProxyOptions | undefined) {
  if (proxy === undefined) return (value: string) => value
  const url = typeof proxy === 'string' ? proxy : proxy.url
  const redacted = url.replace(
    /^([a-z][a-z\d+.-]*:\/\/)([^/@]+)@/i,
    '$1***:***@',
  )
  if (redacted === url) return (value: string) => value
  return (value: string) => value.replaceAll(url, redacted)
}

function safeFilename(name: string): string {
  const filename = name.split(/[\\/]/).at(-1)?.replace(/[^\w.-]/g, '-')
  return filename || 'file'
}

/** { json: true, fullPage: true, depth: 2 } → ["--json", "--full-page", "--depth", "2"] */
export function flagsToArgs(flags: Record<string, unknown>): string[] {
  const args: string[] = []
  for (const [key, value] of Object.entries(flags)) {
    if (value === false || value === null || value === undefined) continue
    const flag = `--${key.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)}`
    const values = Array.isArray(value) ? value : [value]
    for (const item of values) {
      if (item === false || item === null || item === undefined) continue
      args.push(flag)
      if (item !== true) args.push(String(item))
    }
  }
  return args
}

function withSession(
  session: string,
  clientArgs: string[],
  commandArgs: string[],
): string[] {
  return ['--session', session, ...clientArgs, ...commandArgs]
}

function positionalArgs(args: string[]): string[] {
  const positionals: string[] = []
  for (let index = 0; index < args.length; index++) {
    const arg = args[index]!
    if (!arg.startsWith('-')) {
      positionals.push(arg)
    } else if (!arg.includes('=') && FLAGS_WITH_VALUE.has(arg)) {
      index++
    }
  }
  return positionals
}

function flagValue(args: string[], flag: string): string | undefined {
  const prefixed = args.find((arg) => arg.startsWith(`${flag}=`))
  if (prefixed) return prefixed.slice(flag.length + 1)
  const index = args.lastIndexOf(flag)
  return index >= 0 ? args[index + 1] : undefined
}

function outputSpec(args: string[]): FileSpec | undefined {
  const [command, ...rest] = args
  const positionals = positionalArgs(rest)
  if (command === 'screenshot' && positionals.length === 0) {
    const format = flagValue(rest, '--screenshot-format')?.toLowerCase()
    return format === 'jpeg'
      ? { ext: 'jpeg', contentType: 'image/jpeg' }
      : { ext: 'png', contentType: 'image/png' }
  }
  if (command === 'pdf' && positionals.length === 0) {
    return { ext: 'pdf', contentType: 'application/pdf' }
  }
  if (
    (command === 'trace' || command === 'profiler') &&
    positionals.length === 1 &&
    positionals[0] === 'stop'
  ) {
    return { ext: 'json', contentType: 'application/json' }
  }
  if (
    command === 'network' &&
    positionals.length === 2 &&
    positionals[0] === 'har' &&
    positionals[1] === 'stop'
  ) {
    return { ext: 'har', contentType: 'application/json' }
  }
  if (
    command === 'state' &&
    positionals.length === 1 &&
    positionals[0] === 'save'
  ) {
    return { ext: 'json', contentType: 'application/json' }
  }
}

/**
 * Create a session-oriented browser client over any CommandRunner.
 *
 * Every command runs as `agent-browser --session <name> <args...>` so the
 * remote daemon keeps page state (refs, cookies, tabs) across calls. Pass an
 * explicit session name to share state across clients, or let it default to
 * an ephemeral per-client session that is closed on `close()`.
 */
export function createBrowserClient(
  runner: CommandRunner,
  opts: BrowserClientOptions = {},
): AgentBrowser {
  const session = opts.session ?? `session-${randomUUID()}`
  if (!SESSION_NAME.test(session)) {
    throw new Error(`session must match [A-Za-z0-9_.-]{1,64}, got "${session}"`)
  }
  const clientArgs = [...(opts.args ?? [])]
  if (opts.proxy !== undefined && hasProxyFlag(clientArgs)) {
    throw new Error('proxy cannot be combined with --proxy or --proxy-bypass args')
  }
  const clientEnv = proxyEnvironment(opts.proxy)
  const redactProxy = proxyOutputRedactor(opts.proxy)
  const ownsRunner = opts.ownsRunner ?? true
  const closeSession = opts.closeSession ?? true
  const recordings = new Map<string, { path: string; spec: FileSpec }>()
  let closed = false

  function assertOpen() {
    if (closed) throw new Error('AgentBrowser is closed')
  }

  async function runWithRedaction(
    cmd: string,
    args: string[],
    options: { timeoutMs?: number; env?: Record<string, string> },
  ): Promise<Awaited<ReturnType<CommandRunner['run']>>> {
    try {
      const run = await runner.run(cmd, args, options)
      return {
        ...run,
        stdout: redactProxy(run.stdout),
        stderr: redactProxy(run.stderr),
      }
    } catch (error) {
      if (error instanceof Error) {
        error.message = redactProxy(error.message)
        if (error.stack) error.stack = redactProxy(error.stack)
      }
      throw error
    }
  }

  async function execCommand(
    args: string[],
    timeoutMs?: number,
    useSession = session,
  ): Promise<BrowserCommandResult> {
    const [name, ...rest] = args
    // File-producing commands get a temporary remote output path when the
    // caller did not provide one. The bytes are pulled back after completion.
    let fileSpec = outputSpec(args)
    const recordAction = name === 'record' ? positionalArgs(rest) : []
    const startsRecording =
      recordAction.length === 1 &&
      (recordAction[0] === 'start' || recordAction[0] === 'restart')
    const stopsRecording =
      recordAction.length === 1 && recordAction[0] === 'stop'

    let finalArgs = withSession(useSession, clientArgs, args)
    let remotePath: string | undefined
    if (fileSpec) {
      remotePath = `/tmp/agent-browser-${randomUUID()}.${fileSpec.ext}`
      finalArgs = withSession(useSession, clientArgs, [
        name!,
        ...rest,
        remotePath,
      ])
    } else if (startsRecording) {
      fileSpec = { ext: 'webm', contentType: 'video/webm' }
      remotePath = `/tmp/agent-browser-${randomUUID()}.webm`
      finalArgs = withSession(useSession, clientArgs, [
        name!,
        recordAction[0]!,
        remotePath,
      ])
    } else if (stopsRecording) {
      const recording = recordings.get(useSession)
      remotePath = recording?.path
      fileSpec = recording?.spec
    }

    const run = await runWithRedaction('agent-browser', finalArgs, {
      timeoutMs,
      env: clientEnv,
    })
    const result: BrowserCommandResult = {
      args,
      ok: run.exitCode === 0,
      exitCode: run.exitCode,
      stdout: run.stdout,
      stderr: run.stderr,
    }
    if (result.ok && startsRecording && remotePath && fileSpec) {
      recordings.set(useSession, { path: remotePath, spec: fileSpec })
    } else if (result.ok && remotePath && fileSpec) {
      try {
        result.file = {
          path: remotePath,
          bytes: await runner.readFile(remotePath),
          contentType: fileSpec.contentType,
        }
      } catch (error) {
        result.ok = false
        result.stderr += `\ncommand succeeded but ${remotePath} could not be read: ${
          error instanceof Error ? error.message : String(error)
        }`
      }
    }
    if (stopsRecording) recordings.delete(useSession)
    return result
  }

  async function exec<T>(
    command: string,
    execOpts: JsonExecOptions,
  ): Promise<BrowserCommandResult<T>>
  async function exec(
    command: string,
    execOpts?: ExecOptions,
  ): Promise<BrowserCommandResult>
  async function exec<T>(
    command: string,
    execOpts: ExecOptions | JsonExecOptions = {},
  ): Promise<BrowserCommandResult | BrowserCommandResult<T>> {
    assertOpen()
    const jsonOutput = execOpts.output === 'json'
    const flags = jsonOutput
      ? { ...execOpts.flags, json: true }
      : execOpts.flags
    const args = [
      command,
      ...(execOpts.args ?? []),
      ...(flags ? flagsToArgs(flags) : []),
    ]
    const useSession = execOpts.session ?? session
    if (!SESSION_NAME.test(useSession)) {
      throw new Error(`session must match [A-Za-z0-9_.-]{1,64}, got "${useSession}"`)
    }
    const result = await execCommand(args, execOpts.timeoutMs, useSession)
    if (!jsonOutput) return result
    if (!result.ok) {
      const details = result.stderr.trim() || result.stdout.trim() || 'unknown error'
      throw new Error(
        `agent-browser ${command} failed with exit code ${result.exitCode}: ${details}`,
      )
    }

    let envelope: unknown
    try {
      envelope = JSON.parse(result.stdout)
    } catch (error) {
      throw new SyntaxError(
        `agent-browser ${command} did not return valid JSON: ${
          error instanceof Error ? error.message : String(error)
        }`,
      )
    }
    if (
      typeof envelope !== 'object' ||
      envelope === null ||
      !('success' in envelope) ||
      envelope.success !== true ||
      !('data' in envelope)
    ) {
      throw new SyntaxError(
        `agent-browser ${command} did not return a successful JSON envelope`,
      )
    }
    return { ...result, data: envelope.data as T } as BrowserCommandResult<T>
  }

  return {
    session,

    async run(commands, runOpts = {}) {
      assertOpen()
      const useSession = runOpts.session ?? session
      if (!SESSION_NAME.test(useSession)) {
        throw new Error(`session must match [A-Za-z0-9_.-]{1,64}, got "${useSession}"`)
      }
      const stopOnError = runOpts.stopOnError ?? true
      const results: BrowserCommandResult[] = []
      // Run each command inside the same CLI session so state carries over.
      for (const command of commands) {
        if (command.length === 0) {
          results.push({
            args: [],
            ok: false,
            exitCode: null,
            stdout: '',
            stderr: 'empty command',
          })
          if (stopOnError) break
          continue
        }
        const result = await execCommand(command, runOpts.timeoutMs, useSession)
        results.push(result)
        if (!result.ok && stopOnError) break
      }
      return {
        session: useSession,
        results,
        ok: results.every((r) => r.ok),
      }
    },

    async shell(
      command: string,
      shellOpts: ShellOptions = {},
    ): Promise<BrowserShellResult> {
      assertOpen()
      if (!command.trim()) throw new Error('shell command must not be empty')
      const useSession = shellOpts.session ?? session
      if (!SESSION_NAME.test(useSession)) {
        throw new Error(`session must match [A-Za-z0-9_.-]{1,64}, got "${useSession}"`)
      }
      const run = await runWithRedaction('sh', ['-c', command], {
        timeoutMs: shellOpts.timeoutMs,
        env: {
          ...clientEnv,
          AGENT_BROWSER_SESSION: useSession,
        },
      })
      return {
        ok: run.exitCode === 0,
        exitCode: run.exitCode,
        stdout: run.stdout,
        stderr: run.stderr,
      }
    },

    exec,

    async upload(selector, files, execOpts = {}) {
      assertOpen()
      if (files.length === 0) throw new Error('upload requires at least one file')
      const remotePaths: string[] = []
      for (const file of files) {
        const remotePath = `/tmp/agent-browser-${randomUUID()}-${safeFilename(file.name)}`
        await runner.writeFile(remotePath, file.bytes)
        remotePaths.push(remotePath)
      }
      return this.exec('upload', {
        ...execOpts,
        args: [selector, ...remotePaths],
      })
    },

    async download(selector, execOpts = {}) {
      assertOpen()
      const remotePath = `/tmp/agent-browser-${randomUUID()}-${safeFilename(
        execOpts.filename ?? 'download',
      )}`
      const result = await this.exec('download', {
        session: execOpts.session,
        timeoutMs: execOpts.timeoutMs,
        args: [selector, remotePath],
      })
      if (!result.ok) throw new Error(`download failed: ${result.stderr || result.stdout}`)
      try {
        result.file = {
          path: remotePath,
          bytes: await runner.readFile(remotePath),
          contentType: 'application/octet-stream',
        }
      } catch (error) {
        throw new Error(
          `download succeeded but ${remotePath} could not be read: ${
            error instanceof Error ? error.message : String(error)
          }`,
        )
      }
      return { file: result.file, result }
    },

    async readFile(path, contentType = 'application/octet-stream') {
      assertOpen()
      if (!path) throw new Error('file path must not be empty')
      return {
        path,
        bytes: await runner.readFile(path),
        contentType,
      }
    },

    async snapshot(urlOrOptions, opts = {}) {
      const url = typeof urlOrOptions === 'string' ? urlOrOptions : undefined
      const runOpts = typeof urlOrOptions === 'string' ? opts : (urlOrOptions ?? {})
      const commands = url ? [['open', url]] : []
      commands.push(['snapshot', '-i', '--json'])
      return this.run(commands, runOpts)
    },

    async screenshot(urlOrOptions, opts = {}) {
      const url = typeof urlOrOptions === 'string' ? urlOrOptions : undefined
      const runOpts = typeof urlOrOptions === 'string' ? opts : (urlOrOptions ?? {})
      const shotArgs = ['screenshot']
      if (runOpts.fullPage) shotArgs.push('--full')
      const commands = url ? [['open', url]] : []
      commands.push(shotArgs)
      const run = await this.run(commands, runOpts)
      const file = run.results.find((r) => r.file)?.file
      if (!file) {
        throw new Error(
          `screenshot failed: ${
            run.results.map((r) => r.stderr || r.stdout).join('\n') || 'no output'
          }`,
        )
      }
      return { png: file.bytes, result: run }
    },

    keepalive(opts: KeepaliveOptions = {}) {
      assertOpen()
      if (!runner.keepalive) {
        throw new Error('the command runner does not support keepalive')
      }
      return runner.keepalive(opts)
    },

    async close() {
      if (closed) return
      closed = true
      // Close the CLI session's browser first so the sandbox can stop cleanly.
      if (closeSession) {
        await runner
          .run('agent-browser', withSession(session, clientArgs, ['close']), {
            timeoutMs: 15_000,
            env: clientEnv,
          })
          .catch(() => {})
      }
      if (ownsRunner) await runner.close()
    },
  }
}

export { DEFAULT_COMMAND_TIMEOUT_MS }

import {
  AgentBrowser,
  type BrowserCommandResult,
} from 'remote-agent-browser'

const browsers = new Map<string, Promise<AgentBrowser>>()

function getBrowser(agentSessionId: string): Promise<AgentBrowser> {
  const existing = browsers.get(agentSessionId)
  if (existing) return existing

  const pending = AgentBrowser.create()
  browsers.set(agentSessionId, pending)
  void pending.catch(() => {
    if (browsers.get(agentSessionId) === pending) {
      browsers.delete(agentSessionId)
    }
  })
  return pending
}

export type BashResult =
  | { handled: false }
  | {
      handled: true
      stdout: string
      stderr: string
      exitCode: number
      file?: BrowserCommandResult['file']
    }

/**
 * Intercept a parsed Bash invocation before passing it to the regular Bash
 * executor. The first argument must be the executable name.
 */
export async function runBrowserCommand(
  agentSessionId: string,
  argv: string[],
): Promise<BashResult> {
  if (argv[0] !== 'agent-browser') return { handled: false }

  const [command, ...args] = argv.slice(1)
  if (!command) {
    return {
      handled: true,
      stdout: '',
      stderr: 'usage: agent-browser <command> [args...]',
      exitCode: 2,
    }
  }

  const browser = await getBrowser(agentSessionId)
  const result = await browser.exec(command, { args })

  return {
    handled: true,
    stdout: result.stdout,
    stderr: result.stderr,
    exitCode: result.exitCode ?? 1,
    file: result.file,
  }
}

/** Close the remote browser when its owning agent session ends. */
export async function closeBrowser(agentSessionId: string): Promise<void> {
  const pending = browsers.get(agentSessionId)
  browsers.delete(agentSessionId)
  if (pending) await (await pending).close()
}

import { createHash } from 'node:crypto'
import { Sandbox } from '@vercel/sandbox'
import type {
  BrowserRuntimeResetEvent,
  CommandRunner,
  KeepaliveOptions,
  SandboxCredentials,
  ResolveSandboxCredentials,
} from './types.js'

const DEFAULT_TIMEOUT_MS = 10 * 60 * 1000
export const DEFAULT_BROWSER_IMAGE = 'remote-agent-browser:latest'

const BASE_ENV = {
  AGENT_BROWSER_ARGS: '--no-sandbox,--disable-dev-shm-usage,--disable-gpu',
  AGENT_BROWSER_DEFAULT_TIMEOUT: '25000',
}

/** CommandRunner backed by one Vercel Sandbox. */
export class SandboxRunner implements CommandRunner {
  protected sandbox: Sandbox | undefined
  protected env: Record<string, string>
  protected timeoutMs: number
  protected readonly resolveSandboxCredentials:
    | ResolveSandboxCredentials
    | undefined
  private keepaliveStops = new Set<() => void>()

  constructor(
    sandbox: Sandbox | undefined,
    env: Record<string, string>,
    timeoutMs = DEFAULT_TIMEOUT_MS,
    resolveSandboxCredentials?: ResolveSandboxCredentials,
  ) {
    this.sandbox = sandbox
    this.env = env
    this.timeoutMs = timeoutMs
    this.resolveSandboxCredentials = resolveSandboxCredentials
  }

  protected async acquire(): Promise<Sandbox> {
    if (!this.sandbox) throw new Error('browser sandbox is unavailable')
    return this.sandbox
  }

  protected async observe(): Promise<Sandbox | null> {
    return this.observeWithCredentials(await this.resolveSandboxCredentials?.())
  }

  protected async observeWithCredentials(
    credentials: SandboxCredentials | undefined,
  ): Promise<Sandbox | null> {
    if (!this.sandbox) return null
    const sandbox = await Sandbox.get({
      ...credentials,
      name: this.sandbox.name,
      resume: false,
    })
    this.sandbox = sandbox
    return sandbox
  }

  protected async destroyRuntime(): Promise<void> {
    if (this.resolveSandboxCredentials) {
      const credentials = await this.resolveSandboxCredentials()
      if (credentials) {
        const sandbox = await this.observeWithCredentials(credentials)
        await sandbox?.stop()
        return
      }
    }
    await this.sandbox?.stop().catch(() => {})
  }

  async run(
    cmd: string,
    args: string[],
    opts: { timeoutMs?: number; env?: Record<string, string> } = {},
  ): Promise<{ stdout: string; stderr: string; exitCode: number | null }> {
    const timeoutMs = opts.timeoutMs ?? 60_000
    // A command is activity: restore the configured idle window even when no
    // explicit heartbeat is running. Renewal is best-effort so an observability
    // or platform hiccup does not block useful browser work.
    const hadSandbox = this.sandbox !== undefined
    let sandbox = await this.acquire()
    if (hadSandbox) {
      const credentials = await this.resolveSandboxCredentials?.()
      if (credentials) {
        const observed = await this.observeWithCredentials(credentials)
        if (!observed) throw new Error('browser sandbox is unavailable')
        sandbox = observed
      } else {
        sandbox =
          (await this.observeWithCredentials(undefined).catch(() => null)) ??
          sandbox
      }
    }
    await this.restoreLifetime(sandbox, this.timeoutMs).catch(() => {})
    const command = await sandbox.runCommand({
      cmd,
      args,
      env: { ...this.env, ...opts.env },
      detached: true,
    })
    let timer: ReturnType<typeof setTimeout> | undefined
    let timedOut = false
    const timeout = new Promise<never>((_, reject) => {
      timer = setTimeout(() => {
        timedOut = true
        reject(new Error(`command timed out after ${timeoutMs}ms`))
      }, timeoutMs)
      if (typeof timer.unref === 'function') timer.unref()
    })
    try {
      const finished = (await Promise.race([command.wait(), timeout])) as
        | { exitCode: number }
        | number
      const exitCode =
        typeof finished === 'number' ? finished : finished.exitCode
      const [stdout, stderr] = await Promise.all([
        command.output('stdout'),
        command.output('stderr'),
      ])
      return { stdout, stderr, exitCode }
    } catch (error) {
      await command.kill().catch(() => {})
      if (timedOut) await this.reclaimBrowser(sandbox)
      throw error
    } finally {
      if (timer) clearTimeout(timer)
    }
  }

  /** A timed-out CLI call may leave Chromium wedged; force a clean relaunch. */
  private async reclaimBrowser(sandbox: Sandbox): Promise<void> {
    try {
      const command = await sandbox.runCommand({
        cmd: 'sh',
        args: [
          '-c',
          'pkill -9 chromium || true; pkill -9 chrome || true',
        ],
        detached: true,
      })
      let timer: ReturnType<typeof setTimeout> | undefined
      const timeout = new Promise<void>((resolve) => {
        // Cleanup must not turn the original command timeout into an unbounded wait.
        timer = setTimeout(resolve, 30_000)
        if (typeof timer.unref === 'function') timer.unref()
      })
      try {
        await Promise.race([command.wait(), timeout])
      } finally {
        if (timer) clearTimeout(timer)
      }
    } catch {}
  }

  async readFile(path: string): Promise<Buffer> {
    const { stdout, exitCode, stderr } = await this.run('base64', ['-w0', path], {
      timeoutMs: 30_000,
    })
    if (exitCode !== 0) {
      throw new Error(`failed to read ${path}: ${stderr.trim()}`)
    }
    return Buffer.from(stdout.trim(), 'base64')
  }

  async writeFile(path: string, bytes: Buffer): Promise<void> {
    const hadSandbox = this.sandbox !== undefined
    let sandbox = await this.acquire()
    if (hadSandbox) {
      const credentials = await this.resolveSandboxCredentials?.()
      if (credentials) {
        const observed = await this.observeWithCredentials(credentials)
        if (!observed) throw new Error('browser sandbox is unavailable')
        sandbox = observed
      }
    }
    await sandbox.writeFiles([{ path, content: bytes }])
  }

  /** Restore a sliding idle window without cumulatively adding that window. */
  private async restoreLifetime(
    sandbox: Sandbox,
    timeoutMs: number,
  ): Promise<void> {
    if (sandbox.status !== 'running') return
    const targetExpiresAt = Date.now() + timeoutMs
    const currentExpiresAt = sandbox.expiresAt?.getTime()
    const extensionMs =
      currentExpiresAt === undefined
        ? timeoutMs
        : Math.ceil(targetExpiresAt - currentExpiresAt)
    if (extensionMs > 0) await sandbox.extendTimeout(extensionMs)
  }

  private async renewLifetime(timeoutMs: number): Promise<void> {
    // Poll without resuming: a late heartbeat must not resurrect an already
    // expired Sandbox whose in-memory browser state is gone.
    const sandbox = await this.observe()
    if (!sandbox) return
    await this.restoreLifetime(sandbox, timeoutMs)
  }

  keepalive(opts: KeepaliveOptions = {}): () => void {
    const timeoutMs = opts.timeoutMs ?? this.timeoutMs
    const intervalMs =
      opts.intervalMs ?? Math.min(5 * 60 * 1000, Math.floor(timeoutMs / 2))
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
      throw new RangeError('keepalive timeoutMs must be greater than 0')
    }
    if (
      !Number.isFinite(intervalMs) ||
      intervalMs <= 0 ||
      intervalMs >= timeoutMs
    ) {
      throw new RangeError(
        'keepalive intervalMs must be greater than 0 and less than timeoutMs',
      )
    }

    let stopped = false
    let renewing = false
    const tick = async () => {
      if (stopped || renewing) return
      renewing = true
      try {
        await this.renewLifetime(timeoutMs)
      } catch (error) {
        opts.onError?.(error)
      } finally {
        renewing = false
      }
    }
    const timer = setInterval(() => void tick(), intervalMs)
    timer.unref?.()
    void tick()

    const stop = () => {
      if (stopped) return
      stopped = true
      clearInterval(timer)
      this.keepaliveStops.delete(stop)
    }
    this.keepaliveStops.add(stop)
    return stop
  }

  async close(): Promise<void> {
    for (const stop of [...this.keepaliveStops]) stop()
    await this.destroyRuntime()
  }
}

type NamedBrowserSandboxOptions = {
  id: string
  image?: string
  timeoutMs?: number
  vcpus?: number
  env?: Record<string, string>
  resolveSandboxCredentials?: ResolveSandboxCredentials
}

function stableNames(id: string): { sandbox: string; session: string } {
  const hash = createHash('sha256').update(id).digest('hex')
  return {
    sandbox: `remote-browser-${hash.slice(0, 32)}`,
    session: `session-${hash.slice(0, 32)}`,
  }
}

function isMissingSandbox(error: unknown): boolean {
  if (!(error instanceof Error)) return false
  const code = (error as Error & { json?: { error?: { code?: string } } }).json
    ?.error?.code
  return code === 'not_found' || error.message.includes('Status code 404')
}

class NamedSandboxRunner extends SandboxRunner {
  readonly session: string
  private readonly id: string
  private readonly name: string
  private readonly image: string
  private readonly vcpus: number
  private readonly resetListeners = new Set<
    (event: BrowserRuntimeResetEvent) => void
  >()

  constructor(opts: NamedBrowserSandboxOptions) {
    const names = stableNames(opts.id)
    const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS
    super(
      undefined,
      { ...BASE_ENV, ...opts.env },
      timeoutMs,
      opts.resolveSandboxCredentials,
    )
    this.id = opts.id
    this.name = names.sandbox
    this.session = names.session
    this.image =
      opts.image ??
      process.env.REMOTE_AGENT_BROWSER_IMAGE ??
      DEFAULT_BROWSER_IMAGE
    this.vcpus = opts.vcpus ?? 2
  }

  private readonly onResume = async () => {
    const event: BrowserRuntimeResetEvent = {
      id: this.id,
      reason: 'resumed',
    }
    for (const listener of this.resetListeners) {
      try {
        listener(event)
      } catch {}
    }
  }

  on(
    event: 'reset',
    listener: (event: BrowserRuntimeResetEvent) => void,
  ): () => void {
    if (event !== 'reset') throw new Error(`unsupported browser event: ${event}`)
    this.resetListeners.add(listener)
    return () => this.resetListeners.delete(listener)
  }

  protected override async acquire(): Promise<Sandbox> {
    if (this.sandbox) return this.sandbox
    this.sandbox = await Sandbox.getOrCreate({
      ...(await this.resolveSandboxCredentials?.()),
      name: this.name,
      image: this.image,
      resources: { vcpus: this.vcpus },
      timeout: this.timeoutMs,
      ports: [],
      env: this.env,
      persistent: false,
      onResume: this.onResume,
    })
    return this.sandbox
  }

  protected override async observeWithCredentials(
    credentials: SandboxCredentials | undefined,
  ): Promise<Sandbox | null> {
    try {
      const sandbox = await Sandbox.get({
        ...credentials,
        name: this.name,
        resume: false,
        onResume: this.onResume,
      })
      this.sandbox = sandbox
      return sandbox
    } catch (error) {
      if (isMissingSandbox(error)) return null
      throw error
    }
  }

  protected override async destroyRuntime(): Promise<void> {
    try {
      const credentials = await this.resolveSandboxCredentials?.()
      let sandbox = this.sandbox
      if (credentials || !sandbox) {
        sandbox = await Sandbox.get({
          ...credentials,
          name: this.name,
          resume: false,
        })
      }
      await sandbox.delete()
      this.sandbox = undefined
    } catch (error) {
      if (!isMissingSandbox(error)) throw error
    }
  }
}

/** Create a lazy runner backed by a stable, project-scoped browser id. */
export function createNamedBrowserSandboxRunner(
  opts: NamedBrowserSandboxOptions,
): NamedSandboxRunner {
  return new NamedSandboxRunner(opts)
}

/**
 * Start an ephemeral Vercel Sandbox from the pre-built browser image.
 *
 * The image must already exist in the Sandbox project's Vercel Container
 * Registry and contain both `agent-browser` and Chromium. A repository name,
 * tag, digest, or fully-qualified VCR reference is accepted by the SDK.
 */
export async function provisionBrowserSandbox(opts: {
  image?: string
  timeoutMs?: number
  vcpus?: number
  env?: Record<string, string>
  resolveSandboxCredentials?: ResolveSandboxCredentials
}): Promise<SandboxRunner> {
  const image =
    opts.image ??
    process.env.REMOTE_AGENT_BROWSER_IMAGE ??
    DEFAULT_BROWSER_IMAGE
  const env = { ...BASE_ENV, ...opts.env }
  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS
  const sandbox = await Sandbox.create({
    ...(await opts.resolveSandboxCredentials?.()),
    image,
    resources: { vcpus: opts.vcpus ?? 2 },
    timeout: timeoutMs,
    ports: [],
    env,
    persistent: false,
  })

  return new SandboxRunner(
    sandbox,
    env,
    timeoutMs,
    opts.resolveSandboxCredentials,
  )
}

